package com.focusflow.api.entity; import jakarta.persistence.*; import java.time.*; @Entity public class Task { @Id @GeneratedValue(strategy=GenerationType.UUID) public String id; @Column(nullable=false) public String title; @Column(length=3000) public String description; @Enumerated(EnumType.STRING) public Status status=Status.TODO; @Enumerated(EnumType.STRING) public Priority priority=Priority.MEDIUM; public String category; public LocalDate dueDate; public LocalTime dueTime; public Instant reminder; public Instant completedAt; public Instant createdAt=Instant.now(); public Instant updatedAt=Instant.now(); @ManyToOne(optional=false,fetch=FetchType.LAZY) public AppUser user; @PreUpdate void updated(){updatedAt=Instant.now();} public enum Status { TODO, IN_PROGRESS, COMPLETED } public enum Priority { LOW, MEDIUM, HIGH, URGENT } }
